import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { createFileLink } from "../handlers/createFileLink";
import type { ApiError } from "../runtime/client";
import type { CreateFileLinkRequest } from "../types/CreateFileLinkRequest";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof createFileLink>>;
type Vars = { spacePk: SpacePartition; req: CreateFileLinkRequest };

export function useCreateFileLink(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => createFileLink(vars.spacePk, vars.req),
    ...options,
  });
}
